    assert abs(roles["chaser"]["dx"]) > abs(roles["chaser"]["dy"]), f"Chaser should pursue directly: {roles}"
    assert abs(roles["spitter"]["dy"]) > abs(roles["spitter"]["dx"]), f"Spitter should orbit instead of only pursuing: {roles}"
    assert roles["brute"]["dx"] > roles["chaser"]["dx"], f"Brute should have a distinct slow-then-surge movement cycle: {roles}"
    assert abs(roles["hexer"]["dy"]) > 0 and roles["hexer"] != roles["spitter"], f"Hexer should strafe differently from the spitter: {roles}"
    assert "function drawMiniMap()" in HTML and "drawMiniMap();" in HTML, "A compact in-room minimap should be drawn during play"
