    assert fire["explosive"]["explosive"], f"Wybuchowy must carry its area-damage behavior: {fire}"
    assert fire["spread"]["dps"] <= fire["standard"]["dps"] * 3.0, f"Spread's theoretical all-pellets-hit ceiling should reflect a strong close-range reward: {fire}"
    assert fire["burst"]["dps"] <= fire["standard"]["dps"] * 3.0, f"Salwa's all-pellets-hit ceiling must be high but limited by its long firing interval and spread: {fire}"
    ttk = page.evaluate("window.__testWeaponTtk()")
