    boss_reward = page.evaluate("window.__testBossReward()")
    assert boss_reward["drops"] == ["item"] and boss_reward["rewardCategory"] in ("legs", "shot"), f"Boss should guarantee one movement/shooting stat item and no coin/heart drops: {boss_reward}"
    assert boss_reward["exitDoors"] == 1 and boss_reward["floorExitSpawned"] and "piętro 3" in boss_reward["log"].lower() and boss_reward["coins"] == 0 and boss_reward["killChain"] == 5, f"Boss should unlock one special exit and announce next floor: {boss_reward}"
    trail_item = page.evaluate("window.__testTrailItem()")
    assert trail_item["enabled"] and abs(trail_item["damage"]-1.25)<0.001 and "pola zadające obrażenia" in trail_item["description"] and trail_item["trailCount"] == 1 and trail_item["enemyDamage"] > 0, f"Stalowe Obcasy should increase damage and enable a damaging floor trail: {trail_item}"

    bossClear = page.evaluate("window.__testBossClear()")
    assert bossClear["doorOpen"], f"Clearing a room should open its doors: {bossClear}"
    bossTransition = page.evaluate("window.__testBossTransition()")
    assert bossTransition["floor"] == 2 and bossTransition["roomNo"] == 1 and bossTransition["bosses"] == 1, f"Descending should start floor 2 with its boss in room 1: {bossTransition}"
    page.locator("#weaponBtn").click()
    assert page.evaluate("window.__smoke()['state']") == "firingChoice", "The in-run weapon button should open weapon selection"
    assert page.locator("#fireChoices .moveChoice").count() == 7, "The in-run weapon selector should expose all seven weapons"
    page.locator("#fireChoices .moveChoice").first.click()
    assert page.evaluate("window.__smoke()['state']") == "play", "Choosing a weapon mid-run should return to gameplay, not force movement selection"
    assert "BROŃ: Precyzyjny" in page.locator("#weaponBtn").inner_text(), "Weapon button should display the selected weapon"
    page.locator("#movementBtn").click()
    assert page.evaluate("window.__smoke()['state']") == "movementChoice", "The movement button should open movement selection"
    page.locator("#moveChoices .moveChoice").first.click()
    assert page.evaluate("window.__smoke()['state']") == "play", "Movement selection should return to gameplay"
    page.keyboard.press("v")
    assert page.evaluate("window.__smoke()['state']") == "movementChoice", "V should open movement selection"
    page.keyboard.press("Escape")
    assert page.evaluate("window.__smoke()['state']") == "movementChoice", "Movement overlay should remain until a choice is made"
    page.locator("#moveChoices .moveChoice").first.click()
    page.keyboard.press("m")
    assert page.evaluate("window.__smoke()['state']") == "play" and page.evaluate("window.__smoke()['mapOpen']"), "M should open the floor map without opening movement selection"
    page.evaluate("window.__testRestart()")
    assert page.evaluate("window.__smoke()['state']") == "firingChoice", "Restart should reset the run and reopen firing-style selection"
    assert not errors, f"Browser errors: {errors}"
    print("PASS: connected 6x5 floor grid and reversible directional links; full map toggle; functional rock/pit/vent hazards; Polish in-game guide; enemy HP scaling by floor and door tier; startup pickups; full-HP heart persistence; shop purchase; exit probabilities and placement; room-30 edge exit and bonus; boss-room clearing and floor transition, boss reward and special exit, damaging trail item; named 30-item catalogue; all ten active-item effects; all 20 passive-item effects; active-item kill accounting; six movement physics styles; six distinct enemy movement roles; minimap and persistent weapon/movement buttons; readable shop text; movement acceleration, coast, reversal, diagonal speed and automatic burst cadence; shooting; restart; no browser errors")
    browser.close()
